examples.template:
MonarchFlowLayout(spacing: theme.spacing.space4) {
    Button({{links.0.label}}) {}
        .buttonStyle(.monarchLink({{links.0.variant|case}}))
    Button({{links.1.label}}) {}
        .buttonStyle(.monarchLink({{links.1.variant|case}}))
    Button({{links.2.label}}) {}
        .buttonStyle(.monarchLink({{links.2.variant|case}}))
    if let url = URL(string: {{links.3.href}}) {
        Link({{links.3.label}}, destination: url)
            .buttonStyle(.monarchLink({{links.3.variant|case}}, isExternal: {{links.3.external}}))
    }
}
.monarchTextStyle(.body)

examples.code:
MonarchFlowLayout(spacing: theme.spacing.space4) {
    Button("Inline link") {}
        .buttonStyle(.monarchLink(.inline))
    Button("Standalone link") {}
        .buttonStyle(.monarchLink(.standalone))
    Button("Subtle link") {}
        .buttonStyle(.monarchLink(.subtle))
    if let url = URL(string: "https://rookhq.com") {
        Link("Rook website", destination: url)
            .buttonStyle(.monarchLink(.inline, isExternal: true))
    }
}
.monarchTextStyle(.body)

VStack(alignment: .leading) {
    MonarchTextField("Password", text: $password, isSecure: true)
    Button("Forgot password?") { showsReset = true }
        .buttonStyle(.monarchLink(.subtle))
        .monarchTextStyle(.caption)
}
